/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# 3D heat diffusion kernel (Jacobi-style 7-point stencil).
# A and B are stored in DRAM in row-major order with k as the fastest-varying index.

@proc
def kernel_heat_3d(
    tsteps: size,
    n: size,
    A: DATA_TYPE[n, n, n] @ DRAM,
    B: DATA_TYPE[n, n, n] @ DRAM,
):
    # We update only interior points; boundaries are left unchanged.
    assert n > 2

    for t in seq(0, tsteps):
        # First sweep: update B from A.
        for i in seq(1, n - 1):
            for j in seq(1, n - 1):
                for k in seq(1, n - 1):
                    B[i, j, k] = (
                        0.125 * (A[i + 1, j,     k    ] - 2.0 * A[i, j, k] + A[i - 1, j,     k    ])
                      + 0.125 * (A[i,     j + 1, k    ] - 2.0 * A[i, j, k] + A[i,     j - 1, k    ])
                      + 0.125 * (A[i,     j,     k + 1] - 2.0 * A[i, j, k] + A[i,     j,     k - 1])
                      + A[i, j, k]
                    )

        # Second sweep: update A from B.
        for i in seq(1, n - 1):
            for j in seq(1, n - 1):
                for k in seq(1, n - 1):
                    A[i, j, k] = (
                        0.125 * (B[i + 1, j,     k    ] - 2.0 * B[i, j, k] + B[i - 1, j,     k    ])
                      + 0.125 * (B[i,     j + 1, k    ] - 2.0 * B[i, j, k] + B[i,     j - 1, k    ])
                      + 0.125 * (B[i,     j,     k + 1] - 2.0 * B[i, j, k] + B[i,     j,     k - 1])
                      + B[i, j, k]
                    )

# ---------------------------------------------------------------------------
# Scheduling: tile the spatial loops (i, j) in both stencil sweeps.
#
# Motivation:
#   - Each update touches a 3x3x3 neighborhood around (i,j,k).
#   - Tiling i and j improves cache locality by working on small 2D blocks
#     in the i-j plane while streaming along the contiguous k dimension.
#   - We keep k as the innermost loop to preserve unit-stride accesses.
#
# TI/TJ are tunable tile sizes; they can be adjusted per target machine.
# ---------------------------------------------------------------------------

TI = 8   # tile size in the i dimension
TJ = 8   # tile size in the j dimension

p = kernel_heat_3d

# ---- First sweep: A -> B ----
# Original loop nest (inside the t-loop):
#   for i in seq(1, n - 1):
#     for j in seq(1, n - 1):
#       for k in seq(1, n - 1):
#         ...
#
# Step 1: tile the i-loop.
p = divide_loop(p, "i #0", TI, ("ioA", "iiA"), tail="guard")

# Step 2: tile the j-loop inside that sweep.
p = divide_loop(p, "j #0", TJ, ("joA", "jiA"), tail="guard")

# After tiling, loop order is: t, ioA, iiA, joA, jiA, k.
# Step 3: reorder to iterate tiles in (ioA, joA) and points in (iiA, jiA, k).
# This gives better 2D blocking in the (i, j) plane.
p = reorder_loops(p, "iiA joA")

# ---- Second sweep: B -> A ----
# Apply the same tiling pattern to the second triply nested loop.
p = divide_loop(p, "i", TI, ("ioB", "iiB"), tail="guard")
p = divide_loop(p, "j", TJ, ("joB", "jiB"), tail="guard")
p = reorder_loops(p, "iiB joB")

# Export the scheduled version under the original kernel name.
kernel_heat_3d = p
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_3D_ARRAY_DECL(A, DATA_TYPE, N, N, N, n, n, n);
  POLYBENCH_3D_ARRAY_DECL(B, DATA_TYPE, N, N, N, n, n, n);

