/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Tunable blocking factors for the 3D spatial domain.
# These can be adjusted when (re)generating the kernel to better fit the cache
# hierarchy of a particular machine.
TI = 8   # tile size in the i (x) dimension
TJ = 8   # tile size in the j (y) dimension
TK = 32  # tile size in the k (z) dimension; keep k relatively large for stride-1 access


@proc
def kernel_heat_3d(
    tsteps: size,
    n: size,
    A: DATA_TYPE[n, n, n] @ DRAM,
    B: DATA_TYPE[n, n, n] @ DRAM,
):
    # The stencil touches i±1, j±1, k±1, so we require at least 3 points.
    assert n > 2

    # Time-stepping loop.
    for t in seq(0, tsteps):
        # ------------------------------------------------------------------
        # Phase 1: update B from A.
        #
        # We work on the interior points only; the halo on A is read but not
        # written, and the halo on B is left unchanged.
        #
        # Induction variables i, j, k run over 0 .. n-3. All accesses are
        # shifted by +1 so that the updated point is (i+1, j+1, k+1).
        # This makes the loop bounds 0-based and enables straightforward
        # tiling via scheduling primitives.
        # ------------------------------------------------------------------
        for i in seq(0, n - 2):
            for j in seq(0, n - 2):
                for k in seq(0, n - 2):
                    B[i + 1, j + 1, k + 1] = (
                        0.125 * (
                            A[i + 2, j + 1, k + 1]
                            - 2.0 * A[i + 1, j + 1, k + 1]
                            + A[i,     j + 1, k + 1]
                        )
                      + 0.125 * (
                            A[i + 1, j + 2, k + 1]
                            - 2.0 * A[i + 1, j + 1, k + 1]
                            + A[i + 1, j,     k + 1]
                        )
                      + 0.125 * (
                            A[i + 1, j + 1, k + 2]
                            - 2.0 * A[i + 1, j + 1, k + 1]
                            + A[i + 1, j + 1, k]
                        )
                      + A[i + 1, j + 1, k + 1]
                    )

        # ------------------------------------------------------------------
        # Phase 2: update A from B (same stencil, roles swapped).
        # ------------------------------------------------------------------
        for i in seq(0, n - 2):
            for j in seq(0, n - 2):
                for k in seq(0, n - 2):
                    A[i + 1, j + 1, k + 1] = (
                        0.125 * (
                            B[i + 2, j + 1, k + 1]
                            - 2.0 * B[i + 1, j + 1, k + 1]
                            + B[i,     j + 1, k + 1]
                        )
                      + 0.125 * (
                            B[i + 1, j + 2, k + 1]
                            - 2.0 * B[i + 1, j + 1, k + 1]
                            + B[i + 1, j,     k + 1]
                        )
                      + 0.125 * (
                            B[i + 1, j + 1, k + 2]
                            - 2.0 * B[i + 1, j + 1, k + 1]
                            + B[i + 1, j + 1, k]
                        )
                      + B[i + 1, j + 1, k + 1]
                    )


# ----------------------------------------------------------------------
# Scheduling: cache-friendly tiling + simple CSE + OpenMP parallelism.
# ----------------------------------------------------------------------

# Start from the object code procedure.
p = kernel_heat_3d

# 1) Common-subexpression elimination for the stencil center values that are
#    used multiple times. This introduces scalar temporaries and reduces
#    memory traffic for the central A/B loads in each stencil evaluation.
p = bind_expr(p, p.find_all("A[i + 1, j + 1, k + 1]"), "a_center")
p = bind_expr(p, p.find_all("B[i + 1, j + 1, k + 1]"), "b_center")

# 2) Tile the spatial loops of phase 1 (update B from A).
#    We tile the i, j, and k loops using the tunable factors TI/TJ/TK.
#    The 'guard' tail strategy ensures correctness when n-2 is not
#    divisible by the tile size.
p = divide_loop(p, "i", TI, ["io0", "ii0"], tail="guard")
p = divide_loop(p, "j", TJ, ["jo0", "ji0"], tail="guard")
p = divide_loop(p, "k", TK, ["ko0", "ki0"], tail="guard")

# 3) Tile the spatial loops of phase 2 (update A from B) in the same way,
#    but with distinct iterator names to keep the structure clear.
p = divide_loop(p, "i", TI, ["io1", "ii1"], tail="guard")
p = divide_loop(p, "j", TJ, ["jo1", "ji1"], tail="guard")
p = divide_loop(p, "k", TK, ["ko1", "ki1"], tail="guard")

# 4) Parallelize the outermost i-tiles of each phase.  Each time-step
#    phase reads from one array and writes to the other, so these tile
#    loops are embarrassingly parallel.
p = parallelize_loop(p, "io0")
p = parallelize_loop(p, "io1")

# 5) Final minor clean-ups (constant folding, dead-code elimination).
p = simplify(p)

# Replace the original definition with the scheduled one so that the
# generated C symbol is still called 'kernel_heat_3d'.
kernel_heat_3d = p
EXO END
*/


int main(int argc, char** argv)
{
